+import type { Trait } from '../trait/types';
+import { $aspect } from './symbols';
+import type { Aspect, AspectInput, ExtractAspectTraits } from './types';
+
+let aspectId = 0;
+
+export function isAspect(value: unknown): value is Aspect {
+    return Boolean((value as Aspect | null | undefined)?.[$aspect]);
+}
+
+export function createAspect<T extends readonly [AspectInput, AspectInput, ...AspectInput[]]>(
+    ...inputs: T
+): Aspect<ExtractAspectTraits<T>> {
+    const traits: Trait[] = [];
+    const fields = new Set<string>();
+
+    for (const input of inputs) {
+        const constituents = isAspect(input) ? input.traits : [input];
+        for (const trait of constituents) {
+            if (isRelation(trait)) throw new Error('Koota: Relations cannot be aspect constituents.');
+            for (const field of Object.keys(trait.schema)) {
+                if (fields.has(field)) {
+                    throw new Error(`Koota: Aspect constituents cannot share the field "${field}".`);
+                }
+                fields.add(field);
+            }
+            traits.push(trait);
+        }
+    }
+
+    const schema = Object.assign({}, ...traits.map((trait) => trait.schema));
+    return Object.freeze({ [$aspect]: true as const, id: aspectId++, traits, schema }) as Aspect<
+        ExtractAspectTraits<T>
+    >;
+}
