+function createAspectQueryResult<T extends QueryParameter[]>(
+    world: World,
+    entities: Entity[],
+    _query: QueryInstance,
+    params: QueryParameter[]
+): QueryResult<T> {
+    const inputs = getDataInputs(params);
+    const results = Object.assign(entities, {
+        readEach(callback: any) {
+            for (let i = 0; i < entities.length; i++) callback(inputs.map((input) => entities[i].get(input as any)), entities[i], i);
+            return results;
+        },
+        updateEach(callback: any, _options?: QueryResultOptions) {
+            for (let i = 0; i < entities.length; i++) {
+                const entity = entities[i];
+                const state = inputs.map((input) => entity.get(input as any));
+                callback(state, entity, i);
+                if (!world.has(entity)) continue;
+                for (let j = 0; j < inputs.length; j++) entity.set(inputs[j] as any, state[j]);
+            }
+            return results;
+        },
+        useStores(callback: any) {
+            callback([], entities);
+            return results;
+        },
+        select<U extends QueryParameter[]>(...selectParams: U) {
+            return createAspectQueryResult<U>(world, entities, _query, selectParams);
+        },
+        sort(callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)) {
+            Array.prototype.sort.call(entities, callback);
+            return results;
+        },
+    });
+    return results as QueryResult<T>;
+}
+
+function getDataInputs(params: QueryParameter[]): (Trait | Aspect)[] {
+    const inputs: (Trait | Aspect)[] = [];
+    for (const param of params) {
+        if (isAspect(param)) inputs.push(param);
+        else if (isModifier(param)) {
+            if (param.type === 'not') continue;
+            inputs.push(...(param.inputs ?? param.traits));
+        } else if (!isRelationPair(param) && (param as Trait)[$internal].type !== 'tag') inputs.push(param as Trait);
+    }
+    return inputs.filter((input) => !isAspect(input) || input.traits.some((trait) => trait[$internal].type !== 'tag'));
